const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const { mkdtempSync, rmSync } = require('node:fs');
const { tmpdir } = require('node:os');
const path = require('node:path');
const { test } = require('node:test');

test('preset transactions preserve the previous file through failed writes, closes, and commits', () => {
  const directory = mkdtempSync(path.join(tmpdir(), 'wled-file-transaction-'));
  const binary = path.join(directory, 'file-transaction-test');
  try {
    execFileSync(process.env.CXX || 'c++', ['-std=c++17', '-Wall', '-Wextra', '-Werror',
      path.join(__dirname, 'file-transaction-test.cpp'), '-o', binary], { stdio: 'pipe' });
    assert.doesNotThrow(() => execFileSync(binary, [], { stdio: 'pipe' }));
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});
